INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-flugplanung-1','cl-flugplanung',1,'entwurf','{"title":"Flugplanung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop mit den Fahrlehrern erarbeitet."},{"key":"s1i2","type":"item","text":"Fahrtgebiet, Startplatz und mögliche Landegebiete festgelegt"},{"key":"s1i3","type":"item","text":"Fahrtdauer und Alternativen geplant"},{"key":"s1i4","type":"item","text":"Begleitfahrzeug, Crew und Kommunikation organisiert"},{"key":"s1i5","type":"item","text":"Checklisten Meteo, Luftraum, Masse und Flugplanaufgabe durchgegangen"}]}]}','fehlt','fehlt',4,'Erstfassung aus Vorlage: Workshop',NULL,1792908000000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-meteo-entscheid','g1','beide',0,2,NULL,NULL,1792908001000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-meteo-entscheid-1','cl-meteo-entscheid',1,'entwurf','{"title":"Meteo und Entscheidungskriterien","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop erarbeitet; ComOPS und Privatbetrieb unterscheiden."}]},{"title":"Wetter","items":[{"key":"s2i1","type":"item","text":"Wetterbriefing eingeholt (GAFOR, TAF/METAR, Windprofil, Gewitter, Inversion)"},{"key":"s2i2","type":"item","text":"Bodenwind am Startplatz unter {{bodenwind_max}} erwartet","var":"bodenwind_max"},{"key":"s2i3","type":"item","text":"Wind in der Höhe und im Landegebiet beurteilt"},{"key":"s2i4","type":"item","text":"Sicht und Wolkenuntergrenze über die ganze Fahrt VMC"}]},{"title":"Entscheid","items":[{"key":"s3i1","type":"item","text":"Trockenheit und Brandgefahr geprüft (eigene Checkliste)"},{"key":"s3i2","type":"item","text":"Go/No-Go entschieden und Crew informiert"}]}]}','fehlt','fehlt',6,'Erstfassung aus Vorlage: Workshop',NULL,1792908001000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-luftraum','g1','beide',0,3,NULL,NULL,1792908002000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-luftraum-1','cl-luftraum',1,'entwurf','{"title":"Luftraum","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop erarbeitet."},{"key":"s1i2","type":"item","text":"DABS und NOTAM für den Fahrttag geprüft"},{"key":"s1i3","type":"item","text":"Luftraumstruktur entlang der Route geprüft (CTR, TMA, Gefahren- und Sperrgebiete)"},{"key":"s1i4","type":"item","text":"Freigaben und Frequenzen notiert"},{"key":"s1i5","type":"item","text":"Transponder- und Funkpflicht geklärt"},{"key":"s1i6","type":"item","text":"Höhenmessereinstellgebiet und QNH bekannt"}]}]}','fehlt','fehlt',5,'Erstfassung aus Vorlage: Workshop',NULL,1792908002000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-flugplanaufgabe','g1','beide',0,4,NULL,NULL,1792908003000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-flugplanaufgabe-1','cl-flugplanaufgabe',1,'entwurf','{"title":"Flugplanaufgabe","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop erarbeitet. Pflicht unter anderem bei Nachtfahrten (spätestens 3 Std. vorher) und bei Grenzübertritt."},{"key":"s1i2","type":"item","text":"Flugplan nötig? (Nacht, Grenzübertritt, Luftraumvorgabe)"},{"key":"s1i3","type":"item","text":"Flugplan auf skybriefing.com eingereicht"},{"key":"s1i4","type":"item","text":"Aktivierung und Schliessung des Flugplans geregelt"}]}]}','fehlt','fehlt',3,'Erstfassung aus Vorlage: Workshop',NULL,1792908003000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-masse-gasreserven','g1','heissluft',0,5,NULL,NULL,1792908004000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-masse-gasreserven-1','cl-masse-gasreserven',1,'entwurf','{"title":"Masse und Gasreserven","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop erarbeitet (MTOW, MLW, Gasreserven, maximale Passagieranzahl). Werte aus dem Ballonmuster."}]},{"title":"Masse","items":[{"key":"s2i1","type":"item","text":"Startmasse berechnet und unter {{mtom}}","var":"mtom"},{"key":"s2i2","type":"item","text":"Landemasse über {{mlm}}","var":"mlm"},{"key":"s2i3","type":"item","text":"Höchstens {{pax_max}} Passagiere (Versicherung, Korbfläche)","var":"pax_max"}]},{"title":"Gas","items":[{"key":"s3i1","type":"item","text":"Gasvorrat für Fahrtdauer plus Reserve berechnet"},{"key":"s3i2","type":"item","text":"Mindestens {{flaschen_min}} Flaschen, alle voll","var":"flaschen_min"},{"key":"s3i3","type":"item","text":"Bei Nachtfahrt 40 % Mehrverbrauch berücksichtigt"}]}]}','fehlt','fehlt',6,'Erstfassung aus Vorlage: Workshop',NULL,1792908004000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-trockenheit','g1','heissluft',0,6,NULL,NULL,1792908005000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-trockenheit-1','cl-trockenheit',1,'entwurf','{"title":"Trockenheit und Brandgefahr","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Nach Merkblatt «Ballonfahren bei Trockenheit» (SBAV, Version 2, Juli 2026). Ergänzt das Flight Manual, ersetzt es nicht."}]},{"title":"Vor der Fahrt","items":[{"key":"s2i1","type":"item","text":"Waldbrandgefahr sowie kantonale und kommunale Verbote für Start- und Landegebiet geprüft"},{"key":"s2i2","type":"item","text":"Startplatz unmittelbar vor dem Aufrüsten kontrolliert: Heu, Stroh, dürres Gras bei Brenner und Ventilator entfernt, Arbeitsbereich wenn möglich angefeuchtet"},{"key":"s2i3","type":"item","text":"Flammtuch vor dem Aufheizen am Brennerrahmen eingehängt (sofern möglich)"},{"key":"s2i4","type":"item","text":"Fahrzeuge nicht über trockenem Gras oder Stroh abgestellt (Katalysator bis 400 °C)"}]},{"title":"Briefing","items":[{"key":"s3i1","type":"item","text":"Alle wissen, wo Feuerlöscher, Löschdecke und Mobiltelefon sind; Schaumlöscher griffbereit"},{"key":"s3i2","type":"item","text":"Kinder und nicht eingewiesene Personen halten beim Aufheizen Abstand; Rauchverbot für alle"}]},{"title":"Start und Landung","items":[{"key":"s4i1","type":"item","text":"Ventilator sofort nach der Kaltfüllung abgestellt; kein Heu oder Stroh in die Hülle geblasen"},{"key":"s4i2","type":"item","text":"Bei Gasgeruch, Undichtigkeit, unkontrollierter Flamme oder Entstehungsbrand Aufheizen sofort abgebrochen"},{"key":"s4i3","type":"item","text":"Landeplatz mit kurzem grünem Bewuchs, blankem Boden, Kies oder feuchtem Untergrund gewählt – Stoppelfelder und trockenes Heu gemieden"}]},{"title":"Nach der Landung","items":[{"key":"s5i1","type":"item","text":"Gaszufuhr und Pilotflammen so bald wie möglich geschlossen; Korb wenn möglich senkrecht stehen gelassen"},{"key":"s5i2","type":"item","text":"Start- und Landeplatz sowie Standplatz des Begleitfahrzeugs auf Rauch, Glut, Brandgeruch und erwärmte Stellen kontrolliert"},{"key":"s5i3","type":"note","text":"Bei Brand: Feuerwehr 118 oder Notruf 112 mit genauem Standort."}]}]}','fehlt','fehlt',11,'Erstfassung aus Vorlage: Merkblatt Trockenheit',NULL,1792908005000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-aufruesten','g2','heissluft',0,1,NULL,NULL,1792908006000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-aufruesten-1','cl-aufruesten',1,'entwurf','{"title":"Aufrüsten","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – Standardverfahren nach AFM, wird im Workshop erarbeitet."},{"key":"s1i2","type":"item","text":"Startplatz, Windrichtung, Hindernisse und Zuschauerabstand beurteilt"},{"key":"s1i3","type":"item","text":"Korb, Brenner, Flaschen und Hülle gemäss AFM geprüft und verbunden"},{"key":"s1i4","type":"item","text":"Brennertest durchgeführt, Druck zwischen {{brennerdruck_min}} und {{brennerdruck_max}}","var":"brennerdruck_min"},{"key":"s1i5","type":"item","text":"Crew eingewiesen (Checkliste Crew-Einweisung)"},{"key":"s1i6","type":"item","text":"Kaltfüllung mit Ventilator, Aufrichten mit Brenner; Ventilator danach sofort aus"}]}]}','fehlt','fehlt',5,'Erstfassung aus Vorlage: Workshop',NULL,1792908006000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-crew-einweisung','g2','heissluft',0,2,NULL,NULL,1792908007000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-crew-einweisung-1','cl-crew-einweisung',1,'entwurf','{"title":"Crew-Einweisung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0 (Kronleinen-Crew, Hüllenöffnung-Crew, Quick-Release)."}]},{"title":"Kronenseil","items":[{"key":"s2i1","type":"item","text":"Handschuhe und festes Schuhwerk"},{"key":"s2i2","type":"item","text":"Kronenseil am Ende halten, mit 20–40 kg Zug die Hülle stabilisieren; Seil nie um Hand oder Körper wickeln, im Notfall loslassen"},{"key":"s2i3","type":"item","text":"Sobald der Ventilator aus ist und der Pilot heizt, langsam zum Korb gehen; stoppen, sobald die Hülle senkrecht steht"}]},{"title":"Hüllenöffnung","items":[{"key":"s3i1","type":"item","text":"Handschuhe; Kleidung aus Naturfasern oder nicht brennbar, Arme und Beine bedeckt; keine losen Teile, lange Haare zusammengebunden"},{"key":"s3i2","type":"item","text":"Seile straff halten, nicht zwischen den Tragseilen stehen"},{"key":"s3i3","type":"item","text":"Ventilator parallel zur Hülle; auf Signal des Piloten abschalten"},{"key":"s3i4","type":"item","text":"Nach dem Aufrichten Korb halten und beschweren"},{"key":"s3i5","type":"item","text":"Eine Person hält die Zuschauer auf sicherem Abstand"}]},{"title":"Quick-Release","items":[{"key":"s4i1","type":"item","text":"Zuschauer zwischen Ankerpunkt und Ballon fernhalten"},{"key":"s4i2","type":"item","text":"Nur der Pilot betätigt das Quick-Release"}]}]}','fehlt','fehlt',10,'Erstfassung aus Vorlage: Entwurf V0',NULL,1792908007000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-passagiereinweisung','g2','heissluft',0,3,NULL,NULL,1792908008000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-passagiereinweisung-1','cl-passagiereinweisung',1,'entwurf','{"title":"Passagiereinweisung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0 – Sicherheitshinweise FR/EN (DGAC) als Dokument hinterlegt."}]},{"title":"Vor der Fahrt","items":[{"key":"s2i1","type":"item","text":"Kleidung für Höhe und Kälte; Sonnenbrille, Kopfschutz, Sonnencreme, Getränke und Esswaren"}]},{"title":"Vor dem Start","items":[{"key":"s3i1","type":"item","text":"Rauchverbot im Umkreis von 30 m"},{"key":"s3i2","type":"item","text":"Anweisungen des Piloten befolgen; sicherer Abstand zum Ventilator"},{"key":"s3i3","type":"item","text":"Nichts aus dem Korb werfen; Hände und Arme bleiben im Korb"},{"key":"s3i4","type":"item","text":"Nicht festhalten an Brennstoffschläuchen, Steuerleinen, Brennerhebeln oder Flaschenventilen"}]},{"title":"Landung","items":[{"key":"s4i1","type":"item","text":"Lose Gegenstände vor der Landung verstauen"},{"key":"s4i2","type":"item","text":"Landeposition gezeigt: Füsse zusammen, ganze Sohle am Korbboden, Knie leicht gebeugt, Griffe im Korb halten, Kopf unter der oberen Polsterung"},{"key":"s4i3","type":"item","text":"Nicht am Korbrand oder an den Brennerstützen festhalten"},{"key":"s4i4","type":"item","text":"Auf Umkippen des Korbes gefasst sein; im Korb bleiben bis zur Erlaubnis des Piloten"},{"key":"s4i5","type":"note","text":"Kurz vor der Landung das Landeverfahren nochmals wiederholen."}]}]}','fehlt','fehlt',9,'Erstfassung aus Vorlage: Entwurf V0',NULL,1792908008000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-start-check','g2','heissluft',0,4,NULL,NULL,1792908009000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-start-check-1','cl-start-check',1,'entwurf','{"title":"Start-Check","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – Standardverfahren vor dem Abheben, wird im Workshop erarbeitet."},{"key":"s1i2","type":"item","text":"Passagiere eingewiesen und in Position"},{"key":"s1i3","type":"item","text":"Instrumente ein, Funk auf Frequenz, Transponder gesetzt"},{"key":"s1i4","type":"item","text":"Flaschenventile offen, Brenner und Pilotflammen geprüft"},{"key":"s1i5","type":"item","text":"Crew bereit; Quick-Release nur durch den Piloten"},{"key":"s1i6","type":"item","text":"Steigrate nach dem Start begrenzt auf {{steigrate_max}}","var":"steigrate_max"}]}]}','fehlt','fehlt',5,'Erstfassung aus Vorlage: Workshop',NULL,1792908009000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-start','g3','heissluft',0,1,NULL,NULL,1792908010000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-start-1','cl-start',1,'entwurf','{"title":"Start","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – Standardverfahren, wird im Workshop erarbeitet."},{"key":"s1i2","type":"item","text":"Luftraum über dem Startplatz frei, Hindernisse in Fahrtrichtung beurteilt"},{"key":"s1i3","type":"item","text":"Abheben kontrolliert, Steigrate höchstens {{steigrate_max}}","var":"steigrate_max"},{"key":"s1i4","type":"item","text":"Begleitfahrzeug informiert (Richtung, voraussichtliche Fahrtdauer)"}]}]}','fehlt','fehlt',3,'Erstfassung aus Vorlage: Workshop',NULL,1792908010000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-fahrt','g4','heissluft',0,1,NULL,NULL,1792908011000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-fahrt-1','cl-fahrt',1,'entwurf','{"title":"Fahrt","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – Standardverfahren, wird im Workshop erarbeitet."},{"key":"s1i2","type":"item","text":"Höhe, Steig- und Sinkrate innerhalb der Betriebsgrenzen"},{"key":"s1i3","type":"item","text":"Gasvorrat und Verbrauch regelmässig geprüft; Flaschenwechsel nach AFM"},{"key":"s1i4","type":"item","text":"Luftraum und Frequenzen beachtet, Position gemeldet wo nötig"},{"key":"s1i5","type":"item","text":"Landegebiet frühzeitig beurteilt (Wind, Hindernisse, Zufahrt, Brandgefahr)"}]}]}','fehlt','fehlt',4,'Erstfassung aus Vorlage: Workshop',NULL,1792908011000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-landung','g5','heissluft',0,1,NULL,NULL,1792908012000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-landung-1','cl-landung',1,'entwurf','{"title":"Landung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0. Grenzen für Ventil und Parachute: siehe Betriebsgrenzen."}]},{"title":"Vorbereitung","items":[{"key":"s2i1","type":"item","text":"Passagiere informiert, Landeverfahren wiederholt, Landeposition eingenommen"},{"key":"s2i2","type":"item","text":"Begleitmannschaft informiert"},{"key":"s2i3","type":"item","text":"Pilot angeschnallt (Rückhaltesystem)"},{"key":"s2i4","type":"item","text":"Windscherung beachtet"}]},{"title":"Landephase","items":[{"key":"s3i1","type":"item","text":"Auf 1 m sinken und parallel zum Boden fahren"},{"key":"s3i2","type":"item","text":"Flaschenventile zu, letztes Mal heizen, Pilotflamme aus"},{"key":"s3i3","type":"item","text":"Parachuteleine ziehen, bis der Ballon stillsteht"},{"key":"s3i4","type":"item","text":"Schnellentleerung (falls installiert) erst bei höchstens 2 m Höhe (Boden bis Korbunterkante)"},{"key":"s3i5","type":"item","text":"Passagiere vor dem Bodenkontakt informiert"}]},{"title":"Nach der Landung","items":[{"key":"s4i1","type":"item","text":"Alle bleiben im Korb, bis der Pilot das Aussteigen freigibt"}]}]}','fehlt','fehlt',10,'Erstfassung aus Vorlage: Entwurf V0',NULL,1792908012000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-reissbahnlandung','g5','heissluft',0,2,NULL,NULL,1792908013000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-reissbahnlandung-1','cl-reissbahnlandung',1,'entwurf','{"title":"Reissbahnlandung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop erarbeitet (Standardlandung und Reissbahnlandung)."},{"key":"s1i2","type":"item","text":"Reissbahnlandung entschieden (Wind, Platz); Begleitmannschaft informiert"},{"key":"s1i3","type":"item","text":"Passagiere: Position für schnelle Landung, Griffe festhalten"},{"key":"s1i4","type":"item","text":"Flaschenventile zu, Pilotflamme aus vor dem Bodenkontakt"},{"key":"s1i5","type":"item","text":"Reissbahn beim Aufsetzen vollständig öffnen"}]}]}','fehlt','fehlt',4,'Erstfassung aus Vorlage: Workshop',NULL,1792908013000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-abruesten','g6','heissluft',0,1,NULL,NULL,1792908014000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-abruesten-1','cl-abruesten',1,'entwurf','{"title":"Abrüsten","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – Standardverfahren, wird im Workshop erarbeitet."},{"key":"s1i2","type":"item","text":"Hülle entleert; Flaschenventile zu, Schläuche entleert"},{"key":"s1i3","type":"item","text":"Hülle, Korb und Brenner kontrolliert, Schäden notiert"},{"key":"s1i4","type":"item","text":"Material verladen; Landeplatz auf Glut und Brandgeruch kontrolliert und sauber hinterlassen"}]}]}','fehlt','fehlt',3,'Erstfassung aus Vorlage: Workshop',NULL,1792908014000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-grundeigentuemer','g6','beide',0,2,NULL,NULL,1792908015000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-grundeigentuemer-1','cl-grundeigentuemer',1,'entwurf','{"title":"Grundeigentümer und Landwirt","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Nach Faktenblatt SBAV/SBV «Tipps für Landwirte und Ballonfahrer». Zutrittsrecht zur Bergung besteht (ZGB Art. 700), keine pauschale Landegebühr; entstandene Schäden sind zu ersetzen. Der Pilot verantwortet das Verhalten des ganzen Teams."},{"key":"s1i2","type":"item","text":"Grundeigentümer oder Landwirt wenn möglich angesprochen, Bergung erklärt; Ruhezeiten respektiert"},{"key":"s1i3","type":"item","text":"Begleitfahrzeug nur auf Wegen, nicht auf kultiviertem Land; Fahrverbote eingehalten"},{"key":"s1i4","type":"item","text":"Zäune und Tore sofort wieder geschlossen; Abstand zu Tieren (Pferde, Mutterkühe, Herdenschutzhunde)"},{"key":"s1i5","type":"item","text":"Schäden und Umtriebe sofort gemeldet, Kontaktdaten ausgetauscht, Entschädigung vereinbart"},{"key":"s1i6","type":"item","text":"Abfälle mitgenommen, Verschmutzungen beseitigt; höflich geblieben, keine Konflikte"}]}]}','fehlt','fehlt',5,'Erstfassung aus Vorlage: Faktenblatt SBAV/SBV',NULL,1792908015000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nachbereitung','g6','beide',0,3,NULL,NULL,1792908016000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nachbereitung-1','cl-nachbereitung',1,'entwurf','{"title":"Nachbereitung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop erarbeitet."},{"key":"s1i2","type":"item","text":"Flugplan geschlossen (falls aufgegeben)"},{"key":"s1i3","type":"item","text":"Bordbuch und Flugbuch nachgeführt"},{"key":"s1i4","type":"item","text":"Mängel gemeldet; Flaschen zum Füllen bereitgestellt"}]}]}','fehlt','fehlt',3,'Erstfassung aus Vorlage: Workshop',NULL,1792908016000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-borddokumente','g8','beide',0,1,NULL,NULL,1792908017000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-borddokumente-1','cl-borddokumente',1,'entwurf','{"title":"Borddokumente","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop erarbeitet."},{"key":"s1i2","type":"item","text":"Lufttüchtigkeitszeugnis und Prüfbericht (ARC) gültig"},{"key":"s1i3","type":"item","text":"Eintragungsschein und Lärmzeugnis an Bord"},{"key":"s1i4","type":"item","text":"Versicherungsnachweis gültig und an Bord"},{"key":"s1i5","type":"item","text":"Flughandbuch (AFM) und Bordbuch an Bord"},{"key":"s1i6","type":"item","text":"Lizenz, Medical und Funkzeugnis des Piloten gültig"},{"key":"s1i7","type":"item","text":"Bei Passagierfahrten: Beförderungsscheine ausgefüllt"}]}]}','fehlt','fehlt',6,'Erstfassung aus Vorlage: Workshop',NULL,1792908017000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-mel','g8','heissluft',0,2,NULL,NULL,1792908018000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-mel-1','cl-mel',1,'entwurf','{"title":"Mindestausrüstung (MEL)","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0."},{"key":"s1i2","type":"item","text":"Höhenmesser und Variometer"},{"key":"s1i3","type":"item","text":"Temperaturmessgerät oder Schmelzsicherung"},{"key":"s1i4","type":"item","text":"Zwei zusätzliche Zündquellen (zusätzlich zum Piezozünder)"},{"key":"s1i5","type":"item","text":"Feuerlöscher und Feuerlöschdecke"},{"key":"s1i6","type":"item","text":"Manövrierseil mindestens 25 m (82 ft)"},{"key":"s1i7","type":"item","text":"Uhr mit Stunden, Minuten und Sekunden"},{"key":"s1i8","type":"item","text":"Hilfsmittel zur Bestimmung der Driftrichtung (GPS, Kompass, Karte)"},{"key":"s1i9","type":"item","text":"Erste-Hilfe-Kasten"},{"key":"s1i10","type":"item","text":"Quick-Release"},{"key":"s1i11","type":"item","text":"Schutzhandschuhe für Pilot und Besatzung"},{"key":"s1i12","type":"item","text":"Messer bei Nachtfahrten"},{"key":"s1i13","type":"item","text":"Sauerstoff: ab 10 000 ft nach 30 Min. für den Piloten, ab 13 000 ft für Pilot und Passagiere"}]}]}','fehlt','fehlt',12,'Erstfassung aus Vorlage: Entwurf V0',NULL,1792908018000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-betriebsgrenzen','g8','heissluft',0,3,NULL,NULL,1792908019000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-betriebsgrenzen-1','cl-betriebsgrenzen',1,'entwurf','{"title":"Betriebsgrenzen","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Werte gemäss AFM des Ballonmusters – sie werden aus dem gewählten Ballon eingesetzt. Entwurf V0 (Beispiel Kubicek 3400 m³)."}]},{"title":"Grenzwerte","items":[{"key":"s2i1","type":"item","text":"Bodenwind höchstens {{bodenwind_max}}","var":"bodenwind_max"},{"key":"s2i2","type":"item","text":"Brennerdruck zwischen {{brennerdruck_min}} und {{brennerdruck_max}}","var":"brennerdruck_min"},{"key":"s2i3","type":"item","text":"Mindestens {{flaschen_min}} Propanbehälter","var":"flaschen_min"},{"key":"s2i4","type":"item","text":"Hüllentemperatur höchstens {{huellentemp_max}}","var":"huellentemp_max"},{"key":"s2i5","type":"item","text":"Startmasse höchstens {{mtom}}, Landemasse mindestens {{mlm}}","var":"mtom"},{"key":"s2i6","type":"item","text":"Höchstens {{pax_max}} Passagiere (Versicherung, MTOM, Korbfläche)","var":"pax_max"},{"key":"s2i7","type":"item","text":"Steiggeschwindigkeit höchstens {{steigrate_max}}, Sinkgeschwindigkeit höchstens {{sinkrate_max}}","var":"steigrate_max"}]},{"title":"Hülle, Ventil und Parachute","items":[{"key":"s3i1","type":"item","text":"Zulässige Beschädigung: unterhalb des ersten horizontalen Lastbands; oberhalb höchstens 5 mm in jeder Richtung"},{"key":"s3i2","type":"item","text":"Parachute höchstens {{parachute_max}} geöffnet","var":"parachute_max"},{"key":"s3i3","type":"item","text":"Parachute geschlossen beim schnellen Sinken, beim Heizen, bei Hüllendeformation und beim schnellen Steigen"},{"key":"s3i4","type":"item","text":"Ventil nicht beim Kaltabstieg und nicht nahe der maximalen Steigrate verwenden"}]}]}','fehlt','fehlt',11,'Erstfassung aus Vorlage: Entwurf V0',NULL,1792908019000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-befoerderungsschein','g8','beide',0,4,NULL,NULL,1792908020000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-befoerderungsschein-1','cl-befoerderungsschein',1,'entwurf','{"title":"Beförderungsschein und Schulung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop erarbeitet (Passagierfahrten, ComOPS, Privatbetrieb)."},{"key":"s1i2","type":"item","text":"Betriebsart geklärt: ComOPS (Lufttransportführer) oder Privatbetrieb"},{"key":"s1i3","type":"item","text":"Beförderungsschein je Passagier ausgefüllt und unterschrieben"},{"key":"s1i4","type":"item","text":"Bei Schulung: Ausbildungsauftrag und Berechtigung des Fahrlehrers geklärt"},{"key":"s1i5","type":"item","text":"Versicherungsdeckung für die Betriebsart geprüft"}]}]}','fehlt','fehlt',4,'Erstfassung aus Vorlage: Workshop',NULL,1792908020000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-bewilligungen-landwirte','g8','beide',0,5,NULL,NULL,1792908021000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-bewilligungen-landwirte-1','cl-bewilligungen-landwirte',1,'entwurf','{"title":"Bewilligungen, Landwirte und Aussenlandungen","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Grundlagen: Aussenlandeverordnung (AuLaV, SR 748.132.3), ZGB Art. 700 und 926–929, Beitrag 079 «Aussenlandungen» (April 2025), Faktenblatt SBAV/SBV."}]},{"title":"Rechtslage","items":[{"key":"s2i1","type":"item","text":"Ballone dürfen ausserhalb von Flugplätzen starten und landen; keine BAZL-Bewilligung nötig (Art. 3 und 21 AuLaV)"},{"key":"s2i2","type":"item","text":"Für die Aussenlandung braucht es grundsätzlich kein Einverständnis des Grundeigentümers – das Privatrecht bleibt vorbehalten"},{"key":"s2i3","type":"item","text":"Nur ein gerichtliches Verbot (Art. 258 ZPO, sichtbares Schild) verbietet Landungen generell; private Tafeln sind unwirksam"},{"key":"s2i4","type":"item","text":"Auf Aufforderung des Grundeigentümers abfliegen oder den Ballon entfernen; keine Aussenlandung bei Unfallstellen"}]},{"title":"Startplatz","items":[{"key":"s3i1","type":"item","text":"Einwilligung des Landbesitzers für den Startplatz eingeholt (Image, gutes Einvernehmen)"},{"key":"s3i2","type":"item","text":"Zufahrtsbeschränkungen und Fahrverbote eingehalten; nicht auf kultiviertes Land gefahren"}]},{"title":"Landeplatz","items":[{"key":"s4i1","type":"item","text":"Abgeerntete, gemähte, unbeweidete und nicht eingezäunte Flächen bevorzugt; Schutzgebiete gemieden"},{"key":"s4i2","type":"item","text":"Tiere berücksichtigt: keine Tieffahrten und kein Lärm bei Fluchttieren, Vorsicht bei Mutterkuhherden und Herdenschutzhunden"},{"key":"s4i3","type":"item","text":"Schäden und Umtriebe sofort gemeldet und entschädigt; Kontakt Schweizerischer Ballonverband bei Unstimmigkeiten"}]}]}','fehlt','fehlt',9,'Erstfassung aus Vorlage: Beitrag 079 + Faktenblatt',NULL,1792908021000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-pruefungsfahrt','g8','beide',0,6,NULL,NULL,1792908022000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-pruefungsfahrt-1','cl-pruefungsfahrt',1,'entwurf','{"title":"Prüfungsfahrt FE(B)","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Entwurf – wird im Workshop mit mindestens einem FE(B) erarbeitet: geforderte Standards für die praktische Prüfung."},{"key":"s1i2","type":"item","text":"Prüfungsablauf und Beurteilungskriterien mit dem FE(B) besprochen"},{"key":"s1i3","type":"item","text":"Fahrtvorbereitung vollständig dokumentiert (Meteo, Luftraum, NOTAM, Masse, Gas)"},{"key":"s1i4","type":"item","text":"Standardverfahren nach AFM demonstriert (Aufrüsten, Start, Fahrt, Landung, Abrüsten)"},{"key":"s1i5","type":"item","text":"Notverfahren erklärt und soweit möglich demonstriert"},{"key":"s1i6","type":"item","text":"Entscheidungen begründet (Go/No-Go, Landeplatzwahl)"}]}]}','fehlt','fehlt',5,'Erstfassung aus Vorlage: Workshop (mit FE(B))',NULL,1792908022000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-fesselaufstieg','g9','heissluft',0,1,NULL,NULL,1792908023000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-fesselaufstieg-1','cl-fesselaufstieg',1,'entwurf','{"title":"Fesselaufstieg","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM des Ballonmusters (Kubicek BB34Z, Ultramagic M-90 – Originalentwürfe mit Tabellen als Dokumente). Werte aus dem Ballonmuster."}]},{"title":"Berechtigung und Beladung","items":[{"key":"s2i1","type":"item","text":"Pilot für Fesselaufstiege berechtigt (Ultramagic: mindestens 1 Aufstieg je 48 Monate)"},{"key":"s2i2","type":"item","text":"Flaschenanzahl und Anordnung gemäss AFM (Kubicek: genau 2 × VA70 in der Ecke; Ultramagic: Worthington aussen)"},{"key":"s2i3","type":"item","text":"Höchstens {{fessel_pax_max}} Passagiere (Korbfläche 0.25 m² je Person, Versicherung)","var":"fessel_pax_max"},{"key":"s2i4","type":"item","text":"Startmasse höchstens {{fessel_tom_max}}","var":"fessel_tom_max"}]},{"title":"Fesselung","items":[{"key":"s3i1","type":"item","text":"3 Seile und Ankerpunkte mit Bruchlast mindestens {{fessel_bruchlast_min}}; Karabiner geprüft","var":"fessel_bruchlast_min"},{"key":"s3i2","type":"item","text":"Seile am Hüllenkarabiner befestigt; Seile, Karabiner und Befestigungen ohne Defekte"},{"key":"s3i3","type":"item","text":"Ankerpunkte: Fahrzeuge mit mindestens 2000 kg oder gleichwertige Fixpunkte (Betonblöcke, Baumstämme) innerhalb der Absperrung"},{"key":"s3i4","type":"item","text":"Kein Quick-Release im Fesselbetrieb"}]},{"title":"Platz, Crew und Wetter","items":[{"key":"s4i1","type":"item","text":"Platz abgesperrt, keine Unbeteiligten; Crew geschult (Ein- und Ausstieg hälftig, Beförderungsscheine am Eingang)"},{"key":"s4i2","type":"item","text":"Wind höchstens {{fessel_wind_max}} (Böen eingerechnet); Anemometer vor Ort; Auf- und Abstieg mit Brennerstössen kontrollierbar","var":"fessel_wind_max"},{"key":"s4i3","type":"item","text":"Höhe Korbboden über Grund höchstens {{fessel_hoehe_max}}; Seillänge erlaubt das Ablegen in jede Richtung","var":"fessel_hoehe_max"},{"key":"s4i4","type":"item","text":"Messer im Korb (kurze Befestigungsseile im Notfall kappen)"}]}]}','fehlt','fehlt',12,'Erstfassung aus Vorlage: Entwürfe V0 Kubicek + Ultramagic',NULL,1792908023000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nebeldurchstoss','g9','beide',0,2,NULL,NULL,1792908024000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nebeldurchstoss-1','cl-nebeldurchstoss',1,'entwurf','{"title":"Nebeldurchstossverfahren","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss SERA, VABFP, VRV-L (Art. 24 Abs. 3: national im Luftraum G zugelassen, in der EU verboten) und VFR-RAC. Entwurf V0."}]},{"title":"Voraussetzungen","items":[{"key":"s2i1","type":"item","text":"Pilot berechtigt (Ausbildungsnachweis vorhanden; keine Recency erforderlich)"},{"key":"s2i2","type":"item","text":"Durchstoss vollständig im Luftraum G; über der Nebelschicht mindestens 100 m Luftraum G frei"},{"key":"s2i3","type":"item","text":"Hinderniskarte geprüft: Freileitungen (openinframap.org) und Luftfahrthindernisse (map.geo.admin.ch, Thema Luftfahrt)"}]},{"title":"Wetter","items":[{"key":"s3i1","type":"item","text":"Über dem Nebel VMC"},{"key":"s3i2","type":"item","text":"Nebeluntergrenze höchstens 200 m über dem Startplatz; Schicht höchstens 300 m dick"},{"key":"s3i3","type":"item","text":"Landegebiet nebelfrei, keine Nebelbildung prognostiziert"}]},{"title":"Vor dem Start","items":[{"key":"s4i1","type":"item","text":"Höhenmesser auf QNH des Höhenmessereinstellgebiets (Zürich, Genf, Tessin)"},{"key":"s4i2","type":"item","text":"Transponder Mode S auf 7000 (Mode C genügt nicht)"},{"key":"s4i3","type":"item","text":"Blindübermittlung auf 130.800 MHz vorbereitet: vor dem Start und nach dem Durchstoss"},{"key":"s4i4","type":"item","text":"Briefing Crew und Passagiere: Verfahren, Sinnestäuschungen, geplante Steigrate"},{"key":"s4i5","type":"item","text":"Steigrate so geplant, dass 5 Min. nach dem Start mindestens 300 m über der Nebelobergrenze erreicht sind (max. 800 m in 5 Min. = 2.7 m/s)"},{"key":"s4i6","type":"note","text":"Funkbeispiel: «Traffic Region Zug, HB-BAA, Hot Air Balloon departure in fog from Steinhausen, departure in 1 minute.» Nach dem Durchstoss: «HB-BAA, fog departure completed, above Steinhausen, 4200 ft.»"}]}]}','fehlt','fehlt',11,'Erstfassung aus Vorlage: Entwurf V0',NULL,1792908024000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nachtfahrt','g9','beide',0,3,NULL,NULL,1792908025000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nachtfahrt-1','cl-nachtfahrt',1,'entwurf','{"title":"Nachtfahrt (NVFR)","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss RAC, VRV-L, SERA. Nacht: Ende der bürgerlichen Abenddämmerung bis Beginn der bürgerlichen Morgendämmerung (VFR RAC 4-4-1). Entwurf V0."}]},{"title":"Voraussetzungen","items":[{"key":"s2i1","type":"item","text":"Pilot für Nachtfahrten berechtigt (Eintrag in der Lizenz)"},{"key":"s2i2","type":"item","text":"Flugplan spätestens 3 Std. vor dem Aufstieg eingereicht (skybriefing.com, VFR RAC 4-5-5)"},{"key":"s2i3","type":"item","text":"Tag- und Nachtgrenzen für den Fahrttag bestimmt"}]},{"title":"Ausrüstung","items":[{"key":"s3i1","type":"item","text":"Zusammenstosswarnlicht (ACL) eingeschaltet: rot oder weiss blinkend, 40–140 Blitze/min, 360° horizontal, ±60° vertikal (CS 31HB/GB.65, SERA 3215)"},{"key":"s3i2","type":"item","text":"Handscheinwerfer und 2 Stirnlampen (Reichweite mindestens 60 m) an Bord"},{"key":"s3i3","type":"item","text":"Messer an Bord (ACL-Kabel im Notfall kappen)"}]},{"title":"Betrieb","items":[{"key":"s4i1","type":"item","text":"Transponder Mode S auf 7000 (Mode C genügt nicht)"},{"key":"s4i2","type":"item","text":"Funkverbindung mit dem Flugverkehrsdienst auch in Luftraum G und E, sofern verfügbar (VFR RAC 4-3-2)"},{"key":"s4i3","type":"item","text":"40 % höherer Propanverbrauch berücksichtigt (keine Sonneneinstrahlung)"}]}]}','fehlt','fehlt',9,'Erstfassung aus Vorlage: Entwurf V0',NULL,1792908025000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nf-harte-landung','g7','heissluft',1,1,NULL,NULL,1792908026000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nf-harte-landung-1','cl-nf-harte-landung',1,'entwurf','{"title":"Harte oder schnelle Landung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0 – Körperhaltungen siehe Dokument «Notverfahren»."}]},{"title":"Schnelle, nicht standardmässige Landung","items":[{"key":"s2i1","type":"item","text":"Geeigneten Landeplatz wählen; allenfalls Hülle mit geeignetem Hindernis stoppen"},{"key":"s2i2","type":"item","text":"Passagiere: Haltung für schnelle Landung, Griffe festhalten, Korb erst auf Anweisung verlassen"},{"key":"s2i3","type":"item","text":"Pilot: Rückhaltesystem anziehen"},{"key":"s2i4","type":"item","text":"Flaschen schliessen, Pilotflamme löschen, Schläuche entleeren"},{"key":"s2i5","type":"item","text":"Geringstmögliche Sinkrate beim Bodenkontakt; Parachute vor dem Bodenkontakt vollständig ziehen"}]},{"title":"Harte Landung","items":[{"key":"s3i1","type":"item","text":"Korrekte Körperhaltung, Griffe festhalten, Rückhaltesystem"},{"key":"s3i2","type":"item","text":"Flaschen schliessen, Pilotflamme löschen, Schläuche entleeren"},{"key":"s3i3","type":"item","text":"Parachute vor dem Bodenkontakt vollständig ziehen"}]},{"title":"Notaufstieg","items":[{"key":"s4i1","type":"item","text":"Doppelbrenner aktivieren – Entscheid nicht mehr ändern"}]}]}','fehlt','fehlt',9,'Erstfassung aus Vorlage: Notverfahren V0',NULL,1792908026000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nf-hindernis','g7','heissluft',1,2,NULL,NULL,1792908027000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nf-hindernis-1','cl-nf-hindernis',1,'entwurf','{"title":"Hindernis und Freileitung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0."}]},{"title":"Hohes Hindernis","items":[{"key":"s2i1","type":"item","text":"Ballon im Ausgleich horizontal halten"},{"key":"s2i2","type":"item","text":"Passagiere: Haltung einnehmen, festhalten, nicht aus dem Korb fallen; Pilot Rückhaltesystem"},{"key":"s2i3","type":"item","text":"So bald wie möglich landen, Hilfe anfordern"}]},{"title":"Tiefes Hindernis – Korb bleibt am Boden","items":[{"key":"s3i1","type":"item","text":"So ventilieren, dass der Korb vor dem Hindernis den Boden erreicht"},{"key":"s3i2","type":"item","text":"Flaschenventile schliessen; Parachute ziehen, damit der Ballon am Boden bleibt"},{"key":"s3i3","type":"item","text":"Hilfe anfordern"}]},{"title":"Elektro-Freileitung","items":[{"key":"s4i1","type":"item","text":"Parachute mit roter Leine ziehen und sinken"},{"key":"s4i2","type":"item","text":"Passagiere: Haltung für hohe Sinkrate, Gesicht nach unten, Augen schützen, keine Flaschen oder Metallteile berühren"},{"key":"s4i3","type":"item","text":"Alle Flaschenventile schliessen, Schläuche entleeren; erneutes Abheben verhindern"},{"key":"s4i4","type":"item","text":"Notruf: Strom abschalten lassen, Hilfe anfordern; Korb erst auf Anweisung verlassen"}]}]}','fehlt','fehlt',10,'Erstfassung aus Vorlage: Notverfahren V0',NULL,1792908027000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nf-kollision-huelle','g7','heissluft',1,3,NULL,NULL,1792908028000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nf-kollision-huelle-1','cl-nf-kollision-huelle',1,'entwurf','{"title":"Kollision und Hüllenschaden","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0."}]},{"title":"Kollision mit anderem Ballon","items":[{"key":"s2i1","type":"item","text":"Anderen Piloten warnen; Kontakt Korb–Hülle vermeiden; Vertikalgeschwindigkeit so weit wie möglich reduzieren"},{"key":"s2i2","type":"item","text":"Unterer Ballon: Sinken einleiten, Sinkrate mit Heizen oder Ballast konstant halten; Passagiere Haltung für hohe Sinkrate"},{"key":"s2i3","type":"item","text":"Oberer Ballon: heizen und steigen, eigenen Korb von der fremden Hülle fernhalten – nicht heizen, wenn zu nahe an der fremden Hülle"},{"key":"s2i4","type":"item","text":"Fremde Hülle oben stark beschädigt: Hülle am Korb befestigen, Sinkrate durch kräftiges Heizen kontrollieren, schnellstmöglich landen"}]},{"title":"Beschädigung der eigenen Hülle","items":[{"key":"s3i1","type":"item","text":"Harte Landung vermeiden: heizen, Hülle prall halten (bei geschlossener Füllöffnung durch die Seitenwand heizen)"},{"key":"s3i2","type":"item","text":"Tief fahren, so bald wie praktikabel landen"},{"key":"s3i3","type":"item","text":"Sinkrate durch Heizen, sonst durch Ballastabwurf konstant halten"},{"key":"s3i4","type":"item","text":"Auf harte Landung vorbereiten"}]}]}','fehlt','fehlt',8,'Erstfassung aus Vorlage: Notverfahren V0',NULL,1792908028000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nf-gelaende','g7','heissluft',1,4,NULL,NULL,1792908029000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nf-gelaende-1','cl-nf-gelaende',1,'entwurf','{"title":"Landung in schwierigem Gelände","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0."}]},{"title":"Nebel","items":[{"key":"s2i1","type":"item","text":"Mit höchstens 0.5 m/s sinken; Raum unter dem Korb kontrollieren, Hindernissen ausweichen"}]},{"title":"Trockene Vegetation","items":[{"key":"s3i1","type":"item","text":"Vor der Landung Pilotflamme löschen, Verdampferspirale kühlen, Flaschenventile schliessen"}]},{"title":"Thermik, böiger Wind","items":[{"key":"s4i1","type":"item","text":"Mitten in grosser, offener Fläche landen; schnell sinken, mit Doppelbrenner abfangen"},{"key":"s4i2","type":"item","text":"Pilotflamme löschen; Parachute in Bodennähe vollständig ziehen"}]},{"title":"Wald","items":[{"key":"s5i1","type":"item","text":"Lichtung oder Pfad wählen; Begleitmannschaft informieren; Steuerleinen und Kronenseil kurz halten"},{"key":"s5i2","type":"item","text":"Passagiere Rettungsposition; kontrolliert zwischen den Bäumen sinken; vorher Schläuche entleeren, Pilotflamme aus"},{"key":"s5i3","type":"item","text":"Bleibt der Korb hängen: im Korb bleiben, Hilfe anfordern – am Boden die Hülle frei fallen lassen"}]},{"title":"Bebautes Gebiet","items":[{"key":"s6i1","type":"item","text":"Wie im Wald, zusätzlich Manövrierseil verwenden"}]},{"title":"Wasser","items":[{"key":"s7i1","type":"item","text":"Nichtschwimmer bestimmen, Hilfe anfordern; tief fahren, nahe am Ufer landen, Brennstoff entsprechend verbrauchen"},{"key":"s7i2","type":"item","text":"Ohne Rettungsboot: Hülle so bald wie möglich vom Korb trennen, Korb als Floss nutzen, auf Hilfe warten"}]}]}','fehlt','fehlt',10,'Erstfassung aus Vorlage: Notverfahren V0',NULL,1792908029000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nf-brenner','g7','heissluft',1,5,NULL,NULL,1792908030000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nf-brenner-1','cl-nf-brenner',1,'entwurf','{"title":"Brennerstörung","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0."}]},{"title":"Pilotflamme der ersten Einheit ausgefallen","items":[{"key":"s2i1","type":"item","text":"Mit der zweiten Einheit steigen; Pilotflamme mit der Hauptbrennerflamme zünden"},{"key":"s2i2","type":"item","text":"Brennstoffstand, Schlauchanschlüsse und Druckregler prüfen"}]},{"title":"Beide Pilotflammen ausgefallen","items":[{"key":"s3i1","type":"item","text":"Schlauchsystem prüfen; mit Piezo oder Ersatzzünder zünden"},{"key":"s3i2","type":"item","text":"Bleibt die Störung: Hauptbrenner oder Flüsterbrenner zünden, Flamme klein halten als Pilotflamme; baldmöglichst landen"}]},{"title":"Hauptfahrventil schliesst nicht","items":[{"key":"s4i1","type":"item","text":"Flüssigphase an der Flasche schliessen; Flaschenventil anstelle des Hauptfahrventils verwenden"}]},{"title":"Hauptbrenner ausser Betrieb","items":[{"key":"s5i1","type":"item","text":"Mit der zweiten Einheit heizen; Brennstoffstand, Schläuche und Flaschenventil prüfen; baldmöglichst landen"}]},{"title":"Kein Brenner funktioniert","items":[{"key":"s6i1","type":"item","text":"Brennstoffmenge, Flaschenventile und Schlauchanschlüsse prüfen; neue Flasche anschliessen (Rego: hängengebliebene Dichtung prüfen)"},{"key":"s6i2","type":"item","text":"Bleibt die Störung: auf harte Landung vorbereiten"}]}]}','fehlt','fehlt',8,'Erstfassung aus Vorlage: Notverfahren V0',NULL,1792908030000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nf-brand','g7','heissluft',1,6,NULL,NULL,1792908031000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nf-brand-1','cl-nf-brand',1,'entwurf','{"title":"Brand und Brennstoffleck","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0."}]},{"title":"Brand in der Luft","items":[{"key":"s2i1","type":"item","text":"Alle Flüssigphasen an den Flaschen schliessen; Löschdecke verwenden"},{"key":"s2i2","type":"item","text":"Mit der Löschdecke die Hauptbrennerventile öffnen und den Brennstoff in den Schläuchen verbrauchen"},{"key":"s2i3","type":"item","text":"Brand mit dem Feuerlöscher löschen; so bald wie möglich mit funktionsfähiger Einheit landen"}]},{"title":"Brand am Boden","items":[{"key":"s3i1","type":"item","text":"Alle Flüssigphasen schliessen; Löschdecke; Hauptbrennerventile öffnen, Brennstoff verbrauchen"},{"key":"s3i2","type":"item","text":"Brand mit dem Feuerlöscher löschen; Ballon mit dem roten Seil entleeren"},{"key":"s3i3","type":"item","text":"Lässt sich der Brand nicht löschen: Personen evakuieren"}]},{"title":"Brennstoffleck","items":[{"key":"s4i1","type":"item","text":"Brennstoffzufuhr zum betroffenen Schlauch schliessen; Schlauch über das Hauptbrennerventil leeren"},{"key":"s4i2","type":"item","text":"Kein Propangeruch mehr: unbeschädigte Einheit verwenden; baldmöglichst landen"}]}]}','fehlt','fehlt',8,'Erstfassung aus Vorlage: Notverfahren V0',NULL,1792908031000);
INSERT OR IGNORE INTO checklists (id,group_id,art,ist_notfall,reihenfolge,current_version_id,created_by,created_at) VALUES ('cl-nf-nacht','g7','heissluft',1,7,NULL,NULL,1792908032000);
INSERT OR IGNORE INTO checklist_versions (id,checklist_id,version,status,inhalt_de,status_fr,status_en,item_count,change_note,created_by,created_at) VALUES ('v-nf-nacht-1','cl-nf-nacht',1,'entwurf','{"title":"Nachtfahrt – Störungen","sections":[{"title":"","items":[{"key":"s1i1","type":"note","text":"Gemäss AFM Kubicek. Entwurf V0."}]},{"title":"Anti-Collision-Light bleibt im Hindernis hängen","items":[{"key":"s2i1","type":"item","text":"Durch Aufsteigen lösen, sonst Kabel mit dem Messer durchtrennen"}]},{"title":"Positionslichter ausgefallen","items":[{"key":"s3i1","type":"item","text":"Kabel, Sicherung und Stecker kontrollieren"},{"key":"s3i2","type":"item","text":"Bleibt die Störung: Flugleitstelle informieren"}]}]}','fehlt','fehlt',3,'Erstfassung aus Vorlage: Notverfahren V0',NULL,1792908032000);
INSERT OR IGNORE INTO documents (id,checklist_id,titel,dateiname,r2_key,mime,groesse,reihenfolge,created_by,created_at) VALUES ('doc-meteo-entscheid-merkblatt-trockenheit','cl-meteo-entscheid','Merkblatt «Ballonfahren bei Trockenheit» (SBAV, Version 2, Juli 2026)','merkblatt-trockenheit-sbav-2026-07.pdf','documents/seed/merkblatt-trockenheit-sbav-2026-07.pdf','application/pdf',160264,1,NULL,1792908001000);
INSERT OR IGNORE INTO documents (id,checklist_id,titel,dateiname,r2_key,mime,groesse,reihenfolge,created_by,created_at) VALUES ('doc-trockenheit-merkblatt-trockenheit','cl-trockenheit','Merkblatt «Ballonfahren bei Trockenheit» (SBAV, Version 2, Juli 2026)','merkblatt-trockenheit-sbav-2026-07.pdf','documents/seed/merkblatt-trockenheit-sbav-2026-07.pdf','application/pdf',160264,1,NULL,1792908005000);
